css:
.proximity-container {
    font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
    max-width: 1080px;
    margin: 0 auto;
    padding: 24px;
    color: #1b2733;
    background: linear-gradient(160deg, #f4f1ea 0%, #eef0ec 50%, #e7ece9 100%);
    border-radius: 18px;
}

.proximity-container * {
    box-sizing: border-box;
}

.proximity-header {
    text-align: center;
    padding: 28px 22px 24px;
    background: linear-gradient(135deg, #0d2b3e 0%, #134b5f 55%, #0f5d54 100%);
    color: #f2faf8;
    border-radius: 16px;
    margin-bottom: 18px;
    box-shadow: 0 14px 34px rgba(13, 43, 62, 0.32);
}

.proximity-header h1 {
    margin: 10px 0 10px;
    font-size: 2.4rem;
    font-weight: 800;
    letter-spacing: -0.5px;
    color: #ffffff;
}

.proximity-header-tag {
    display: inline-block;
    font-size: 0.74rem;
    text-transform: uppercase;
    letter-spacing: 1.2px;
    font-weight: 700;
    color: #f5c66b;
    background: rgba(245, 198, 107, 0.14);
    border: 1px solid rgba(245, 198, 107, 0.40);
    padding: 5px 14px;
    border-radius: 999px;
}

.proximity-subtitle {
    margin: 0 auto;
    max-width: 840px;
    font-size: 1rem;
    line-height: 1.55;
    color: #cfe7e2;
}

.proximity-rivals {
    display: flex;
    align-items: stretch;
    gap: 12px;
    margin-bottom: 18px;
}

.proximity-rival {
    flex: 1;
    background: #ffffff;
    border-radius: 14px;
    padding: 14px 18px;
    box-shadow: 0 4px 14px rgba(27, 39, 51, 0.08);
    display: flex;
    flex-direction: column;
    gap: 4px;
}

.proximity-rival-siri { border-left: 5px solid #0f5d54; }
.proximity-rival-disruptor { border-left: 5px solid #d98324; }

.proximity-rival-name {
    font-weight: 800;
    font-size: 1.05rem;
    color: #0d2b3e;
}

.proximity-rival-siri .proximity-rival-name { color: #0f5d54; }
.proximity-rival-disruptor .proximity-rival-name { color: #b86c12; }

.proximity-rival-meta {
    font-size: 0.82rem;
    color: #5a6b78;
    line-height: 1.4;
}

.proximity-rival-vs {
    align-self: center;
    font-size: 1.1rem;
    font-weight: 800;
    text-transform: uppercase;
    letter-spacing: 1px;
    color: #134b5f;
}

.proximity-period-counter {
    display: flex;
    align-items: center;
    gap: 8px;
    flex-wrap: wrap;
    font-size: 0.96rem;
    font-weight: 600;
    color: #46596b;
    margin-bottom: 16px;
    padding: 4px 4px;
}

.proximity-period-counter #currentDay,
.proximity-period-counter #maxPeriods {
    font-weight: 800;
    color: #0f5d54;
}

.proximity-round-name {
    background: rgba(15, 93, 84, 0.14);
    color: #0d5046;
    padding: 3px 12px;
    border-radius: 999px;
    font-size: 0.82rem;
    font-weight: 700;
    margin-left: 4px;
}

.proximity-clock {
    margin-left: auto;
    font-size: 0.82rem;
    font-weight: 700;
    color: #b16812;
    background: rgba(217, 131, 36, 0.14);
    border: 1px solid rgba(217, 131, 36, 0.30);
    padding: 4px 12px;
    border-radius: 999px;
}

.proximity-status-cards {
    display: grid;
    grid-template-columns: repeat(4, 1fr);
    gap: 14px;
    margin-bottom: 16px;
}

.proximity-status-card {
    background: #ffffff;
    border-radius: 14px;
    padding: 16px 16px 14px;
    box-shadow: 0 6px 16px rgba(27, 39, 51, 0.08);
    border-top: 4px solid #134b5f;
}

.proximity-card-ttd { border-top-color: #0f5d54; }
.proximity-card-cost { border-top-color: #134b5f; }
.proximity-card-csat { border-top-color: #7a5bc4; }
.proximity-card-payback { border-top-color: #d98324; }

.proximity-label {
    font-size: 0.74rem;
    text-transform: uppercase;
    letter-spacing: 0.6px;
    font-weight: 700;
    color: #6b7d8a;
}

.proximity-value {
    font-size: 2.5rem;
    font-weight: 800;
    line-height: 1.1;
    margin: 4px 0 2px;
    color: #0d2b3e;
    font-variant-numeric: tabular-nums;
}

.proximity-card-ttd .proximity-value { color: #0f5d54; }
.proximity-card-cost .proximity-value { color: #134b5f; }
.proximity-card-csat .proximity-value { color: #7a5bc4; }
.proximity-card-payback .proximity-value { color: #b86c12; }

.proximity-sublabel {
    font-size: 0.76rem;
    color: #76889a;
    line-height: 1.35;
}

.proximity-card-ttd.proximity-ttd-good { border-top-color: #0f8a4d; }
.proximity-card-ttd.proximity-ttd-good .proximity-value { color: #0f8a4d; }
.proximity-card-ttd.proximity-ttd-bad { border-top-color: #cf3f3f; }
.proximity-card-ttd.proximity-ttd-bad .proximity-value { color: #cf3f3f; }

.proximity-card-csat.proximity-csat-bad { border-top-color: #cf3f3f; }
.proximity-card-csat.proximity-csat-bad .proximity-value { color: #cf3f3f; }
.proximity-card-csat.proximity-csat-good { border-top-color: #0f8a4d; }
.proximity-card-csat.proximity-csat-good .proximity-value { color: #0f8a4d; }

.proximity-card-payback.proximity-payback-good { border-top-color: #0f8a4d; }
.proximity-card-payback.proximity-payback-good .proximity-value { color: #0f8a4d; }
.proximity-card-payback.proximity-payback-bad { border-top-color: #cf3f3f; }
.proximity-card-payback.proximity-payback-bad .proximity-value { color: #cf3f3f; }

.proximity-budget-bar {
    display: flex;
    justify-content: space-between;
    align-items: center;
    background: #ffffff;
    border: 1px solid #e0e6ea;
    color: #46596b;
    padding: 10px 18px;
    border-radius: 12px;
    margin-bottom: 18px;
    font-weight: 700;
    font-size: 0.92rem;
}

.proximity-budget-bar #budgetDisplay {
    font-size: 1.05rem;
    letter-spacing: 0.3px;
    color: #0f5d54;
    font-weight: 800;
}

.proximity-budget-bar.proximity-budget-over #budgetDisplay { color: #cf3f3f; }
.proximity-budget-bar.proximity-budget-tight #budgetDisplay { color: #b86c12; }

.proximity-briefing {
    display: flex;
    gap: 14px;
    background: #ffffff;
    border-left: 5px solid #0f5d54;
    border-radius: 12px;
    padding: 16px 18px;
    margin-bottom: 18px;
    box-shadow: 0 6px 16px rgba(27, 39, 51, 0.07);
}

.proximity-briefing-icon {
    font-size: 1.8rem;
    line-height: 1;
}

.proximity-briefing-title {
    font-weight: 800;
    font-size: 1.08rem;
    color: #0d2b3e;
    margin-bottom: 6px;
}

.proximity-briefing-text {
    font-size: 0.95rem;
    line-height: 1.55;
    color: #3c4d5e;
}

.proximity-briefing-text strong { color: #0f5d54; }
.proximity-briefing-text em { color: #b86c12; font-style: italic; }

.proximity-controls {
    background: #ffffff;
    border-radius: 14px;
    padding: 20px 22px;
    margin-bottom: 18px;
    box-shadow: 0 6px 16px rgba(27, 39, 51, 0.07);
}

.proximity-controls h3 {
    margin: 0 0 14px;
    font-size: 1.12rem;
    font-weight: 800;
    color: #0d2b3e;
    border-bottom: 2px solid #e7ecef;
    padding-bottom: 8px;
}

.proximity-panel label {
    display: block;
    font-weight: 700;
    font-size: 0.92rem;
    color: #2c3d4e;
    margin: 14px 0 6px;
}

.proximity-container select,
.proximity-container input[type="number"] {
    width: 100%;
    padding: 10px 12px;
    border: 1px solid #c5d2d0;
    border-radius: 9px;
    font-size: 0.92rem;
    background-color: #ffffff;
    color: #1b2733;
    transition: border-color 0.15s, box-shadow 0.15s;
}

.proximity-container select:focus,
.proximity-container input[type="number"]:focus {
    outline: none;
    border-color: #0f5d54;
    box-shadow: 0 0 0 3px rgba(15, 93, 84, 0.16);
}

.proximity-container select option {
    background-color: #ffffff;
    color: #1b2733;
}

.proximity-container input[type="range"] {
    width: 100%;
    margin: 8px 0 2px;
    accent-color: #0f5d54;
}

.proximity-range-readout {
    font-size: 0.88rem;
    font-weight: 700;
    color: #46596b;
    margin-top: 4px;
}

.proximity-range-readout span:nth-child(2) {
    color: #0f5d54;
    font-weight: 800;
}

.proximity-hint {
    font-size: 0.8rem;
    color: #76889a;
    margin-top: 10px;
    line-height: 1.45;
    font-style: italic;
    background: #f4f7f6;
    border-left: 3px solid #d98324;
    padding: 8px 12px;
    border-radius: 6px;
}

.proximity-container .btn {
    margin-top: 18px;
    font-weight: 700;
}

.proximity-container .btn-primary {
    background: linear-gradient(135deg, #134b5f 0%, #0f5d54 100%);
    border: none;
    color: #ffffff;
    padding: 11px 26px;
    border-radius: 9px;
    box-shadow: 0 8px 18px rgba(19, 75, 95, 0.32);
}

.proximity-container .btn-primary:hover {
    filter: brightness(1.08);
}

.proximity-container .btn-outline-secondary {
    margin-left: 10px;
    border: 1px solid #c5d2d0;
    color: #5a6b78;
    background: transparent;
}

.proximity-coach {
    background: linear-gradient(160deg, #0d2b3e 0%, #103a4c 100%);
    color: #e1f1ee;
    border-radius: 14px;
    padding: 16px 20px;
    margin-bottom: 18px;
    box-shadow: 0 8px 20px rgba(13, 43, 62, 0.26);
}

.proximity-coach-header {
    font-size: 0.78rem;
    text-transform: uppercase;
    letter-spacing: 1px;
    font-weight: 700;
    color: #f5c66b;
    margin-bottom: 8px;
}

.proximity-coach-body {
    font-size: 0.95rem;
    line-height: 1.55;
}

.proximity-coach-body strong { color: #6fd9c4; }
.proximity-coach-body em { color: #f5c66b; font-style: italic; }

.proximity-history,
.proximity-chart {
    background: #ffffff;
    border-radius: 14px;
    padding: 18px 20px;
    margin-bottom: 18px;
    box-shadow: 0 6px 16px rgba(27, 39, 51, 0.07);
}

.proximity-history h3,
.proximity-chart h3 {
    margin: 0 0 14px;
    font-size: 1.08rem;
    font-weight: 800;
    color: #0d2b3e;
}

.proximity-container table#usfHistoryTable {
    width: 100%;
    font-size: 0.88rem;
    color: #3c4d5e;
}

.proximity-container table#usfHistoryTable th {
    background: #eef4f3;
    color: #134b5f;
    font-weight: 700;
    text-transform: uppercase;
    font-size: 0.72rem;
    letter-spacing: 0.4px;
    padding: 8px 10px;
    border-bottom: 2px solid #d6e2e0;
}

.proximity-container table#usfHistoryTable td {
    padding: 8px 10px;
    border-bottom: 1px solid #eef1f3;
    color: #3c4d5e;
}

.proximity-container table#usfHistoryTable tr:nth-child(even) td {
    background: #f7faf9;
}

.proximity-chart canvas {
    max-width: 100%;
}

@media (max-width: 768px) {
    .proximity-container {
        padding: 14px;
    }
    .proximity-header h1 {
        font-size: 1.7rem;
    }
    .proximity-rivals {
        flex-direction: column;
    }
    .proximity-status-cards {
        grid-template-columns: repeat(2, 1fr);
        gap: 10px;
    }
    .proximity-value {
        font-size: 2rem;
    }
    .proximity-clock {
        margin-left: 0;
    }
    .proximity-period-counter {
        font-size: 0.88rem;
    }
    .proximity-budget-bar {
        flex-direction: column;
        gap: 4px;
        align-items: flex-start;
    }
    .proximity-container .btn-outline-secondary {
        margin-left: 0;
        margin-top: 8px;
        display: block;
        width: 100%;
    }
}


/* ===== v1.1.0 FIX B - completion / board-debrief scorecard (append-only, namespaced) ===== */
.pp-cm { padding: 12px 6px; text-align: center; font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, 'Helvetica Neue', Arial, sans-serif; }
.pp-cm-heading { font-size: 12px; letter-spacing: .08em; text-transform: uppercase; color: #7a8398; margin-bottom: 6px; }
.pp-cm-verdict { font-size: 22px; font-weight: 700; color: #eceff6; margin-bottom: 8px; }
.pp-cm-score { font-size: 16px; color: #eceff6; margin-bottom: 16px; }
.pp-cm-score strong { color: #4f9bd9; }
.pp-cm-sub { font-size: 11px; letter-spacing: .06em; text-transform: uppercase; color: #7a8398; margin-bottom: 8px; }
.pp-cm-targets { display: flex; flex-wrap: wrap; justify-content: center; gap: 8px; margin-bottom: 16px; }
.pp-cm-target { display: inline-flex; align-items: center; gap: 6px; padding: 6px 11px; border-radius: 20px; font-size: 13px; border: 1px solid transparent; }
.pp-cm-target.pp-cm-met { background: rgba(79,155,217,0.16); color: #8fc3ea; border-color: rgba(79,155,217,0.4); }
.pp-cm-target.pp-cm-missed { background: rgba(255,110,110,0.14); color: #ff9d9d; border-color: rgba(255,110,110,0.36); }
.pp-cm-tick { font-weight: 700; }
.pp-cm-metrics { display: flex; flex-wrap: wrap; justify-content: center; gap: 10px; margin-bottom: 16px; }
.pp-cm-metric { display: inline-flex; flex-direction: column; align-items: center; gap: 2px; padding: 9px 13px; background: rgba(120,135,175,0.12); border-radius: 8px; min-width: 92px; }
.pp-cm-metric span { font-size: 11px; letter-spacing: .03em; text-transform: uppercase; color: #7a8398; }
.pp-cm-metric strong { font-size: 16px; color: #eceff6; }
.pp-cm-insights { list-style: none; padding: 0; margin: 0 auto; max-width: 720px; text-align: left; }
.pp-cm-insights li { padding: 9px 13px; margin-bottom: 7px; background: rgba(79,155,217,0.10); border-left: 3px solid #4f9bd9; border-radius: 4px; color: #dde5f1; font-size: 13px; line-height: 1.45; }
@media (max-width: 640px) { .pp-cm-metric { min-width: 70px; } .pp-cm-verdict { font-size: 19px; } }

