(function() {
    'use strict';

    class ProximityPlayAdapter extends USF.SimulationAdapter {
        constructor() {
            super();
            this.name = `Proximity Play`;
            this.version = `1.1.0`;

            this.ROUNDS = [
                { id: 1, titleKey: `briefing_title_r1`, textKey: `briefing_text_r1`, panelId: `round1Panel`, nameKey: `round_name_r1`, clockKey: `clock_r1` },
                { id: 2, titleKey: `briefing_title_r2`, textKey: `briefing_text_r2`, panelId: `round2Panel`, nameKey: `round_name_r2`, clockKey: `clock_r2` },
                { id: 3, titleKey: `briefing_title_r3`, textKey: `briefing_text_r3`, panelId: `round3Panel`, nameKey: `round_name_r3`, clockKey: `clock_r3` },
                { id: 4, titleKey: `briefing_title_r4`, textKey: `briefing_text_r4`, panelId: `round4Panel`, nameKey: `round_name_r4`, clockKey: `clock_r4` }
            ];

            // ---- Numbers reference card (Siri Mattress, Thailand, THB). ----
            this.BUDGET = 180;            // ฿180M one-time transformation budget
            this.MENU_TOTAL = 410;        // ฿410M full menu — 2.3× the budget
            this.PAYBACK_HURDLE = 36;     // CFO: capital payback under 36 months
            this.START_TTD = 9.0;         // order-to-delivery days (stock)
            this.START_COST = 1150;       // ฿/unit freight + handling
            this.START_CSAT = 78;         // CSAT /100
            this.DISRUPTOR_TTD = 2.0;     // disruptor delivers in 2 days
            this.ANNUAL_UNITS = 400000;   // ~฿3.2B revenue at ~฿8,000/mattress

            // Capital cost per proximity move (฿M).
            this.COST_HUB = 35;           // per regional micro-finishing hub
            this.COST_COMPRESS = 60;      // on-demand compression-and-box line
            this.COST_PLATFORM = 45;      // digital made-to-order platform
            this.COST_SCAN = 30;          // 3D-scan firmness fitting
            this.COST_MOBILE = 25;        // mobile / pop-up fitting units

            // Concept "true" answers used for diagnosis flags.
            this.TRUE_GAP = `custom`;
            this.TRUE_COST = `air`;
            this.TRUE_LENS = `distance`;
        }

        initialize(state) {
            if (!state.domainState || Object.keys(state.domainState).length === 0) {
                state.domainState = {
                    ttd: this.START_TTD,          // time-to-demand (days)
                    cost: this.START_COST,        // delivered unit cost (฿)
                    csat: this.START_CSAT,        // customer satisfaction /100
                    payback: 0,                   // blended payback (months); 0 = not yet funded
                    capital: 0,                   // ฿M committed
                    overBudget: false,            // exceeded ฿180M
                    diagnosed: false,             // Round 1 read the proximity problem right
                    localized: false,             // funded at least one hub
                    techFunded: false,            // funded at least one proximity technology
                    spreadThin: false,            // funded everything / diluted bet
                    digitizedOnly: false,         // tech without localization
                    builtFactoryThinking: false,  // chose scale over proximity
                    csatCrash: false,             // launched everywhere and cratered CSAT
                    ttdHistory: [this.START_TTD],
                    costHistory: [this.START_COST],
                    csatHistory: [this.START_CSAT],
                    lastCoach: ``
                };
            }
            if (!state.decisions || Object.keys(state.decisions).length === 0) {
                // Seeded defaults lean toward the classic errors so a blind
                // click-through does NOT auto-win.
                state.decisions = {
                    gap: `export`,
                    costDriver: `handling`,
                    lens: `scale`,
                    urgency: 40,
                    hubs: 0,
                    compress: 0,
                    platform: 0,
                    scan: 0,
                    mobile: 0,
                    sequence: `all`,
                    triage: `firstcome`,
                    shock: `ignore`,
                    rollout: 60,
                    board: `factory`,
                    defense: `tech`,
                    partner: `discount`,
                    conviction: 50
                };
            }
            this._updateBriefing(state);
        }

        validateDecisions(decisions) {
            const state = window.mySimulation.state;
            const round = state.currentPeriod || 1;
            const warn = (k) => window.mySimulation.uiManager.showNotification(window.mySimulation.t(k), `warning`);

            if (round === 1) {
                const ga = document.getElementById(`gapInput`);
                const cd = document.getElementById(`costDriverInput`);
                const le = document.getElementById(`lensInput`);
                const ur = document.getElementById(`urgencyInput`);
                if (ga) decisions.gap = ga.value;
                if (cd) decisions.costDriver = cd.value;
                if (le) decisions.lens = le.value;
                if (ur) decisions.urgency = parseInt(ur.value, 10);
                if (!Number.isFinite(decisions.urgency) || decisions.urgency < 0 || decisions.urgency > 100) {
                    warn(`warn_urgency_range`); return false;
                }
            } else if (round === 2) {
                const hu = document.getElementById(`hubsInput`);
                const co = document.getElementById(`compressInput`);
                const pl = document.getElementById(`platformInput`);
                const sc = document.getElementById(`scanInput`);
                const mo = document.getElementById(`mobileInput`);
                if (hu) decisions.hubs = parseInt(hu.value, 10);
                if (co) decisions.compress = parseInt(co.value, 10);
                if (pl) decisions.platform = parseInt(pl.value, 10);
                if (sc) decisions.scan = parseInt(sc.value, 10);
                if (mo) decisions.mobile = parseInt(mo.value, 10);
                if (!Number.isFinite(decisions.hubs) || decisions.hubs < 0 || decisions.hubs > 3) {
                    warn(`warn_hubs_range`); return false;
                }
                const cap = this._capitalOf(decisions);
                if (cap === 0) { warn(`warn_no_investment`); return false; }
                if (cap > this.BUDGET) {
                    // Over-budget is allowed through but flagged; the CFO will not sign it.
                    window.mySimulation.uiManager.showNotification(window.mySimulation.t(`warn_over_budget`), `warning`);
                }
            } else if (round === 3) {
                const se = document.getElementById(`sequenceInput`);
                const tr = document.getElementById(`triageInput`);
                const sh = document.getElementById(`shockInput`);
                const ro = document.getElementById(`rolloutInput`);
                if (se) decisions.sequence = se.value;
                if (tr) decisions.triage = tr.value;
                if (sh) decisions.shock = sh.value;
                if (ro) decisions.rollout = parseInt(ro.value, 10);
                if (!Number.isFinite(decisions.rollout) || decisions.rollout < 0 || decisions.rollout > 100) {
                    warn(`warn_rollout_range`); return false;
                }
            } else if (round === 4) {
                const bo = document.getElementById(`boardInput`);
                const de = document.getElementById(`defenseInput`);
                const pa = document.getElementById(`partnerInput`);
                const cv = document.getElementById(`convictionInput`);
                if (bo) decisions.board = bo.value;
                if (de) decisions.defense = de.value;
                if (pa) decisions.partner = pa.value;
                if (cv) decisions.conviction = parseInt(cv.value, 10);
                if (!Number.isFinite(decisions.conviction) || decisions.conviction < 0 || decisions.conviction > 100) {
                    warn(`warn_conviction_range`); return false;
                }
            }
            return true;
        }

        _capitalOf(d) {
            return (d.hubs || 0) * this.COST_HUB
                 + (d.compress ? this.COST_COMPRESS : 0)
                 + (d.platform ? this.COST_PLATFORM : 0)
                 + (d.scan ? this.COST_SCAN : 0)
                 + (d.mobile ? this.COST_MOBILE : 0);
        }

        calculateResults(state) {
            const d = state.decisions;
            const ds = state.domainState;
            const round = state.currentPeriod;

            let ttdDelta = 0, costDelta = 0, csatDelta = 0;
            let coachKey = `coach_default`;
            let summaryKey = `sum_default`;

            if (round === 1) {
                // ---- Diagnose the distance to demand. No KPI moves yet, but the
                // quality of the read sets momentum and flags for later rounds. ----
                let reads = 0;
                if (d.gap === this.TRUE_GAP) reads++;
                if (d.costDriver === this.TRUE_COST) reads++;
                if (d.lens === this.TRUE_LENS) reads++;

                if (d.lens === `scale`) {
                    ds.builtFactoryThinking = true;
                    coachKey = `coach_r1_scale`;
                } else if (d.lens === `price`) {
                    coachKey = `coach_r1_price`;
                } else if (d.gap === `none`) {
                    coachKey = `coach_r1_none`;
                } else if (reads === 3) {
                    coachKey = `coach_r1_sharp`;
                } else {
                    coachKey = `coach_r1_partial`;
                }

                // A sharp diagnosis warms up satisfaction (the org knows where to aim).
                if (reads >= 2 && d.urgency >= 60) { csatDelta += 1; }
                else if (d.urgency <= 25) { csatDelta -= 1; coachKey = `coach_r1_slow`; }

                ds.diagnosed = (reads === 3);
                summaryKey = ds.diagnosed ? `sum_r1_good` : (d.lens === `scale` ? `sum_r1_scale` : `sum_r1_weak`);
            } else if (round === 2) {
                // ---- The core capital-allocation decision. ----
                const cap = this._capitalOf(d);
                ds.capital = cap;
                ds.overBudget = cap > this.BUDGET;

                ds.localized = d.hubs >= 1;
                ds.techFunded = (d.compress + d.platform + d.scan + d.mobile) >= 1;
                const movesFunded = (d.hubs >= 1 ? 1 : 0) + d.compress + d.platform + d.scan + d.mobile;
                ds.digitizedOnly = ds.techFunded && !ds.localized;
                // Spread thin = trying to fund 4+ different moves, diluting each.
                ds.spreadThin = movesFunded >= 4;

                // Time-to-demand: localization (finishing near demand) is the big mover;
                // compression speeds the last mile; the platform/scan capture demand.
                ttdDelta -= d.hubs * 1.6;                       // each hub pulls finishing closer
                if (d.compress) ttdDelta -= 1.8;                // compress-and-box ships fast
                if (d.platform) ttdDelta -= 0.6;                // made-to-order capture, modest TTD effect alone
                if (d.scan) ttdDelta -= 0.2;
                if (d.mobile) ttdDelta -= 0.4;

                // Delivered unit cost: compression kills "shipping air"; hubs cut long-haul.
                if (d.compress) costDelta -= 230;               // attacks the ~22% shipping-air share
                costDelta -= d.hubs * 90;                       // shorter, denser regional runs
                if (d.scan) costDelta -= 20;
                if (d.mobile) costDelta += 10;                  // adds a small last-mile cost

                // Satisfaction: configuration + fitting raise it; pure freight does not.
                if (d.platform) csatDelta += 4;
                if (d.scan) csatDelta += 3;
                if (d.mobile) csatDelta += 2;
                csatDelta += d.hubs * 1;

                // ---- Common-error penalties (decision tree). ----
                if (ds.digitizedOnly) {
                    // Digitized the order, not the delivery — TTD barely moves.
                    ttdDelta += 2.5; csatDelta -= 2; coachKey = `coach_r2_digitized`;
                } else if (ds.spreadThin) {
                    // A little of everything — every bet under-resourced, TTD barely moves.
                    ttdDelta += 2.0; costDelta += 80; coachKey = `coach_r2_thin`;
                } else if (ds.overBudget) {
                    coachKey = `coach_r2_overbudget`;
                } else if (!ds.localized && !ds.techFunded) {
                    coachKey = `coach_r2_nothing`;
                } else if (ds.localized && ds.techFunded) {
                    coachKey = `coach_r2_coupled`;
                } else {
                    coachKey = `coach_r2_partial`;
                }

                // Apply, then compute payback from the realized annual savings.
                ds.ttd = this._clamp(ds.ttd + ttdDelta, this.DISRUPTOR_TTD, 12, 1);
                ds.cost = Math.round(this._clamp(ds.cost + costDelta, 600, 1400, 0));
                ds.csat = Math.round(this._clamp(ds.csat + csatDelta, 40, 100, 0));
                ds.payback = this._payback(ds);

                summaryKey = (!ds.overBudget && ds.localized && ds.techFunded && ds.payback > 0 && ds.payback <= this.PAYBACK_HURDLE)
                    ? `sum_r2_good`
                    : (ds.digitizedOnly ? `sum_r2_digitized`
                    : (ds.spreadThin ? `sum_r2_thin`
                    : (ds.overBudget ? `sum_r2_over` : `sum_r2_weak`)));

                // KPI deltas already applied above for round 2; zero them so the shared
                // apply-block below does not double-count.
                ttdDelta = 0; costDelta = 0; csatDelta = 0;
            } else if (round === 3) {
                // ---- Pilot under demand pressure. Sequencing & triage protect CSAT;
                // the shock tests whether you re-allocate inside the fixed budget. ----
                const rollout = d.rollout / 100;

                // Sequencing.
                switch (d.sequence) {
                    case `cluster`:
                        ttdDelta -= 0.6; csatDelta += 5; coachKey = `coach_r3_cluster`; break;
                    case `export`:
                        csatDelta += 1; coachKey = `coach_r3_export`; break;
                    case `all`:
                        // Launch everywhere at once — capacity can't keep up.
                        ds.csatCrash = true;
                        csatDelta -= 16 * rollout; ttdDelta += 1.5 * rollout;
                        coachKey = `coach_r3_all`; break;
                }

                // Capacity triage rule.
                switch (d.triage) {
                    case `cap`:
                        csatDelta += 6; ttdDelta -= 0.4;
                        if (d.sequence === `all`) { ds.csatCrash = false; csatDelta += 6; } // a cap rescues an all-at-once launch
                        break;
                    case `firstcome`:
                        csatDelta -= 6; ttdDelta += 0.8; break;
                    case `discount`:
                        csatDelta -= 3; costDelta += 60; break;
                }

                // Supplier/adoption shock response.
                switch (d.shock) {
                    case `reallocate`:
                        ttdDelta -= 0.5; csatDelta += 4; coachKey = (d.sequence === `cluster` && d.triage === `cap`) ? `coach_r3_resilient` : coachKey; break;
                    case `ignore`:
                        ttdDelta += 1.2; csatDelta -= 5; if (coachKey === `coach_default`) coachKey = `coach_r3_ignore`; break;
                    case `overspend`:
                        ds.overBudget = true; ds.capital = Math.max(ds.capital, this.BUDGET + 60);
                        csatDelta += 2; coachKey = `coach_r3_overspend`; break;
                }

                // Pace sanity: a moderate rollout on a sound model is best.
                if (d.sequence === `cluster` && rollout >= 0.4 && rollout <= 0.8) { csatDelta += 2; }
                else if (rollout >= 0.95 && d.triage !== `cap`) { csatDelta -= 3; ttdDelta += 0.3; }

                ds.payback = this._payback(ds);

                summaryKey = (d.sequence === `cluster` && d.triage === `cap` && d.shock === `reallocate`) ? `sum_r3_good`
                    : (d.sequence === `all` && ds.csatCrash ? `sum_r3_crash`
                    : (d.shock === `overspend` ? `sum_r3_over` : `sum_r3_weak`));
            } else if (round === 4) {
                // ---- Scale the proximity model and defend it. ----
                switch (d.board) {
                    case `proximity`:
                        csatDelta += 3; ttdDelta -= 0.3; coachKey = `coach_r4_proximity`; break;
                    case `factory`:
                        ds.builtFactoryThinking = true; csatDelta -= 4; ttdDelta += 0.6; coachKey = `coach_r4_factory`; break;
                    case `price`:
                        costDelta += 40; csatDelta -= 2; coachKey = `coach_r4_price`; break;
                }

                switch (d.defense) {
                    case `value`:
                        csatDelta += 3; if (d.board === `proximity`) coachKey = `coach_r4_value`; break;
                    case `tech`:
                        csatDelta -= 1; if (coachKey === `coach_default`) coachKey = `coach_r4_tech`; break;
                    case `cost`:
                        csatDelta -= 1; break;
                }

                switch (d.partner) {
                    case `proof`:
                        csatDelta += 4; coachKey = (d.board === `proximity` && d.defense === `value`) ? `coach_r4_winback` : coachKey; break;
                    case `discount`:
                        costDelta += 30; csatDelta += 1; coachKey = (coachKey === `coach_default`) ? `coach_r4_discount` : coachKey; break;
                    case `ignore`:
                        csatDelta -= 3; coachKey = (coachKey === `coach_default`) ? `coach_r4_ignore` : coachKey; break;
                }

                if (d.conviction >= 60) { csatDelta += 2; }
                else if (d.conviction <= 25) { csatDelta -= 2; }

                ds.payback = this._payback(ds);
                summaryKey = (d.board === `proximity` && d.defense === `value` && d.partner === `proof`) ? `sum_r4_good` : `sum_r4_weak`;
            }

            // ---- Shared apply-block (rounds 1, 3, 4; round 2 applied its own). ----
            if (round !== 2) {
                ds.ttd = this._clamp(ds.ttd + ttdDelta, this.DISRUPTOR_TTD, 12, 1);
                ds.cost = Math.round(this._clamp(ds.cost + costDelta, 600, 1400, 0));
                ds.csat = Math.round(this._clamp(ds.csat + csatDelta, 40, 100, 0));
            }

            ds.ttdHistory.push(ds.ttd);
            ds.costHistory.push(ds.cost);
            ds.csatHistory.push(ds.csat);

            const coachMsg = window.mySimulation.t(coachKey);
            ds.lastCoach = coachMsg;
            const coachEl = document.getElementById(`coachText`);
            if (coachEl) coachEl.innerHTML = coachMsg;

            const self = this;
            setTimeout(function() {
                self._updateBriefing({ currentPeriod: state.currentPeriod + 1 });
            }, 500);

            // v1.1.0 FIX A - persist the composite where the gradebook / reporting layer reads it
            const _c = this._composite(ds);
            ds.score = _c;
            if (!ds.performance) ds.performance = {};
            ds.performance.overallScore = _c;
            return {
                period: state.currentPeriod,
                score: _c,
                overallScore: _c,
                ttd: ds.ttd,
                ttdDelta: Math.round(ttdDelta * 10) / 10,
                cost: ds.cost,
                csat: ds.csat,
                capital: ds.capital,
                payback: ds.payback,
                overBudget: ds.overBudget,
                summary: window.mySimulation.t(summaryKey),
                coach: coachMsg
            };
        }

        _clamp(v, lo, hi, dp) {
            const n = Math.max(lo, Math.min(hi, v));
            const f = Math.pow(10, dp);
            return Math.round(n * f) / f;
        }

        // Blended payback (months) from realized cost + time savings vs. the funded capital.
        // Returns 0 when nothing is funded.
        _payback(ds) {
            if (!ds.capital || ds.capital <= 0) return 0;
            const costSaving = Math.max(0, this.START_COST - ds.cost);     // ฿/unit saved
            // Speed lifts conversion/revenue: ~6% per day below the old 9-day baseline,
            // monetised as a modest ฿ contribution per unit per day saved.
            const daysSaved = Math.max(0, this.START_TTD - ds.ttd);
            const speedValue = daysSaved * 40;                              // ฿/unit revenue contribution
            const annualSaving = (costSaving + speedValue) * this.ANNUAL_UNITS; // ฿/yr
            if (annualSaving <= 0) return 999;
            const capitalBaht = ds.capital * 1000000;                       // ฿M -> ฿
            const months = capitalBaht / (annualSaving / 12);
            return Math.round(Math.min(999, months));
        }

        _ttdLabel(v) {
            return `${this._fmtNum(v, 1)} d`;
        }

        _fmtNum(v, dp) {
            const lang = (window.mySimulation && window.mySimulation.language) ? window.mySimulation.language : `en`;
            const s = Number(v).toFixed(dp);
            return lang === `es` ? s.replace(`.`, `,`) : s;
        }

        setupUI(uiManager) {
            uiManager.bind(`currentDay`, `currentPeriod`);
            uiManager.bind(`maxPeriods`, `maxPeriods`);

            const self = this;

            uiManager.bind(`ttdDisplay`, `domainState.ttd`, (v) => {
                const n = Number(v);
                const card = document.querySelector(`.proximity-card-ttd`);
                if (card) {
                    card.classList.toggle(`proximity-ttd-good`, n <= 4);
                    card.classList.toggle(`proximity-ttd-bad`, n >= 8);
                }
                return self._ttdLabel(n);
            });

            uiManager.bind(`costDisplay`, `domainState.cost`, (v) => `฿${self._money(Math.round(Number(v)))}`);

            uiManager.bind(`csatDisplay`, `domainState.csat`, (v) => {
                const n = Math.round(Number(v));
                const card = document.querySelector(`.proximity-card-csat`);
                if (card) {
                    card.classList.toggle(`proximity-csat-bad`, n < self.START_CSAT);
                    card.classList.toggle(`proximity-csat-good`, n >= 85);
                }
                return `${n}`;
            });

            uiManager.bind(`paybackDisplay`, `domainState.payback`, (v) => {
                const n = Math.round(Number(v));
                const card = document.querySelector(`.proximity-card-payback`);
                if (card) {
                    card.classList.toggle(`proximity-payback-good`, n > 0 && n <= self.PAYBACK_HURDLE);
                    card.classList.toggle(`proximity-payback-bad`, n > self.PAYBACK_HURDLE);
                }
                if (!n) return `—`;
                if (n >= 999) return `∞`;
                return `${n} ` + window.mySimulation.t(`unit_months`);
            });

            uiManager.bind(`budgetDisplay`, `domainState.capital`, (v) => {
                const n = Math.round(Number(v));
                const bar = document.querySelector(`.proximity-budget-bar`);
                if (bar) {
                    bar.classList.toggle(`proximity-budget-over`, n > self.BUDGET);
                    bar.classList.toggle(`proximity-budget-tight`, n > 0 && n <= self.BUDGET && (self.BUDGET - n) <= 20);
                }
                return `฿${n}M / ฿${self.BUDGET}M`;
            });

            // Round 1 urgency slider readout.
            const ur = document.getElementById(`urgencyInput`);
            const urReadout = document.getElementById(`urgencyReadout`);
            if (ur && urReadout) {
                urReadout.textContent = ur.value;
                ur.addEventListener(`input`, function() { urReadout.textContent = ur.value; });
            }

            // Round 3 rollout slider readout.
            const ro = document.getElementById(`rolloutInput`);
            const roReadout = document.getElementById(`rolloutReadout`);
            if (ro && roReadout) {
                roReadout.textContent = ro.value;
                ro.addEventListener(`input`, function() { roReadout.textContent = ro.value; });
            }
        }

        _money(n) {
            return Number(n).toLocaleString(`en-US`);
        }

        getChartConfig() {
            return {
                proximityChart: {
                    type: `line`,
                    data: {
                        labels: [],
                        datasets: [
                            {
                                label: `Time-to-demand (days)`,
                                data: [],
                                borderColor: `#0f5d54`,
                                backgroundColor: `rgba(15,93,84,0.12)`,
                                borderWidth: 3,
                                fill: true,
                                tension: 0.25,
                                pointRadius: 5,
                                pointBackgroundColor: `#0f5d54`,
                                yAxisID: `yDays`
                            },
                            {
                                label: `Customer satisfaction (/100)`,
                                data: [],
                                borderColor: `#7a5bc4`,
                                backgroundColor: `rgba(122,91,196,0.08)`,
                                borderWidth: 2,
                                fill: false,
                                tension: 0.25,
                                pointRadius: 4,
                                pointBackgroundColor: `#7a5bc4`,
                                yAxisID: `yScore`
                            },
                            {
                                label: `Delivered unit cost (฿)`,
                                data: [],
                                borderColor: `#d98324`,
                                backgroundColor: `rgba(217,131,36,0.10)`,
                                borderWidth: 2,
                                borderDash: [5, 4],
                                fill: false,
                                tension: 0.25,
                                pointRadius: 4,
                                pointBackgroundColor: `#d98324`,
                                yAxisID: `yCost`
                            }
                        ]
                    },
                    options: {
                        responsive: true,
                        maintainAspectRatio: false,
                        plugins: {
                            legend: { position: `bottom`, labels: { color: `#46596b`, boxWidth: 14 } },
                            title: { display: false }
                        },
                        scales: {
                            yDays: {
                                type: `linear`, position: `left`, beginAtZero: true, max: 12,
                                ticks: { color: `#0f5d54` }, grid: { color: `rgba(27,39,51,0.06)` },
                                title: { display: true, text: `Days`, color: `#0f5d54` }
                            },
                            yScore: {
                                type: `linear`, position: `right`, beginAtZero: true, max: 100,
                                ticks: { color: `#7a5bc4` }, grid: { drawOnChartArea: false },
                                title: { display: true, text: `CSAT /100`, color: `#7a5bc4` }
                            },
                            yCost: {
                                type: `linear`, position: `right`, min: 600, max: 1400, display: false,
                                ticks: { color: `#d98324` }, grid: { drawOnChartArea: false }
                            },
                            x: {
                                ticks: { color: `#76889a` }, grid: { color: `rgba(27,39,51,0.04)` },
                                title: { display: true, text: `Round`, color: `#76889a` }
                            }
                        }
                    }
                }
            };
        }

        getChartData(state) {
            const ds = state.domainState;
            const labels = ds.ttdHistory.map((_, i) => (i === 0 ? window.mySimulation.t(`chart_start`) : `R` + i));
            return {
                proximityChart: {
                    labels: labels,
                    datasets: [
                        { data: ds.ttdHistory.map((v) => Math.round(v * 10) / 10) },
                        { data: ds.csatHistory.map((v) => Math.round(v)) },
                        { data: ds.costHistory.map((v) => Math.round(v)) }
                    ]
                }
            };
        }

        _composite(ds) {
            // v1.1.0 - verbatim v1.0.0 composite formula (KPI scoring + weights unchanged).
            const ttd = Math.round(ds.ttd * 10) / 10;
            const cost = Math.round(ds.cost);
            const csat = Math.round(ds.csat);
            const payback = Math.round(ds.payback);
            const financed = payback > 0 && payback <= this.PAYBACK_HURDLE && !ds.overBudget;
            const ttdScore = Math.max(0, Math.min(100, (this.START_TTD - ttd) / (this.START_TTD - this.DISRUPTOR_TTD) * 100));
            const costScore = Math.max(0, Math.min(100, (this.START_COST - cost) / (this.START_COST - 600) * 100));
            const csatScore = Math.max(0, Math.min(100, (csat - 60) / 40 * 100));
            const paybackScore = financed ? Math.max(0, Math.min(100, (this.PAYBACK_HURDLE - payback) / this.PAYBACK_HURDLE * 100 + 40)) : 0;
            return Math.round(ttdScore * 0.32 + costScore * 0.22 + csatScore * 0.24 + paybackScore * 0.22);
        }

        formatCompletionMessage(summary) {
            // v1.1.0 FIX B - localized board-debrief scorecard (was: framework default that discarded
            // score, tier, targets and insights).
            const t = (window.mySimulation && typeof window.mySimulation.t === 'function')
                ? window.mySimulation.t.bind(window.mySimulation)
                : function (k) { return k; };
            summary = summary || {};
            const score = (summary.composite != null) ? summary.composite : (summary.score != null ? summary.score : 0);
            const verdict = summary.gradeKey ? t(summary.gradeKey) : (summary.performance || '');
            const insights = summary.insights || [];
            const chip = function (ok, label) {
                return '<div class="pp-cm-target ' + (ok ? 'pp-cm-met' : 'pp-cm-missed') + '">'
                    + '<span class="pp-cm-tick">' + (ok ? '✓' : '✗') + '</span><span>' + label + '</span></div>';
            };
            const targets = ''
                + chip(!!summary.frontier, t('tgt_frontier'))
                + chip(!!summary.cheaper, t('tgt_cheaper'))
                + chip(!!summary.delighted, t('tgt_delighted'))
                + chip(!!summary.financed, t('tgt_financed'));
            const metric = function (label, val) {
                return '<div class="pp-cm-metric"><span>' + label + '</span><strong>' + val + '</strong></div>';
            };
            const nz = function (v) { return (v != null) ? v : '-'; };
            const metrics = ''
                + metric(t('kpi_ttd'), nz(summary.ttd) + 'd')
                + metric(t('kpi_cost'), '฿' + nz(summary.cost))
                + metric(t('kpi_csat'), nz(summary.csat))
                + metric(t('kpi_payback'), nz(summary.payback) + 'm');
            const items = insights.map(function (s) { return '<li>' + s + '</li>'; }).join('');
            return ''
                + '<div class="pp-cm">'
                +   '<div class="pp-cm-heading">' + t('comp_heading') + '</div>'
                +   '<div class="pp-cm-verdict">' + verdict + '</div>'
                +   '<div class="pp-cm-score">' + t('comp_score_label') + ': <strong>' + score + '</strong> / 100</div>'
                +   '<div class="pp-cm-sub">' + t('comp_targets_heading') + '</div>'
                +   '<div class="pp-cm-targets">' + targets + '</div>'
                +   '<div class="pp-cm-metrics">' + metrics + '</div>'
                +   (items ? '<ul class="pp-cm-insights">' + items + '</ul>' : '')
                + '</div>';
        }

        getPerformanceSummary(history) {
            if (!history.length) return {};
            const t = (window.mySimulation && typeof window.mySimulation.t === 'function') ? window.mySimulation.t.bind(window.mySimulation) : function (k) { return k; };
            const ds = window.mySimulation.state.domainState;
            const ttd = Math.round(ds.ttd * 10) / 10;
            const cost = Math.round(ds.cost);
            const csat = Math.round(ds.csat);
            const payback = Math.round(ds.payback);

            const fast = ttd <= 4;                                   // beats the wavering partners' 4-day floor
            const frontier = ttd <= 3;                               // near the competitive frontier
            const cheaper = cost <= 950;                             // materially lower delivered cost
            const delighted = csat >= 84;                            // satisfaction lifted toward the frontier
            const financed = payback > 0 && payback <= this.PAYBACK_HURDLE && !ds.overBudget;

            // Composite across the four KPIs (each 0..100), balanced.
            const ttdScore = Math.max(0, Math.min(100, (this.START_TTD - ttd) / (this.START_TTD - this.DISRUPTOR_TTD) * 100));
            const costScore = Math.max(0, Math.min(100, (this.START_COST - cost) / (this.START_COST - 600) * 100));
            const csatScore = Math.max(0, Math.min(100, (csat - 60) / 40 * 100));
            const paybackScore = financed ? Math.max(0, Math.min(100, (this.PAYBACK_HURDLE - payback) / this.PAYBACK_HURDLE * 100 + 40)) : 0;
            // v1.1.0 FIX A - composite delegated to _composite(ds); ttdScore/costScore/csatScore/paybackScore
            // locals above are left in place (now unused, harmless) to keep the scoring diff minimal.
            const composite = this._composite(ds);

            let pattern = `mixed`;
            if (ds.builtFactoryThinking) pattern = `scale`;
            else if (ds.digitizedOnly) pattern = `digitized`;
            else if (ds.spreadThin) pattern = `thin`;
            else if (!financed && (fast || frontier)) pattern = `unfinanced`;
            else if (fast && cheaper && delighted && financed) pattern = `proximity`;

            // v1.1.0 FIX C - tier resolved to an i18n key and localized via t() (was hardcoded English).
            // The headline anti-pattern — reaching for centralized scale / a second factory —
            // disqualifies the two top verdicts even if the KPIs look strong.
            let perfKey = `grade_distance`;
            if (ds.builtFactoryThinking) perfKey = `grade_scaled`;
            else if (frontier && cheaper && delighted && financed && composite >= 78) perfKey = `grade_proximity`;
            else if (fast && financed && delighted) perfKey = `grade_closer`;
            else if (ds.spreadThin) perfKey = `grade_diluted`;
            else if (ds.digitizedOnly) perfKey = `grade_digitized`;
            else if (!financed && fast) perfKey = `grade_unfinanceable`;
            else if (composite >= 55) perfKey = `grade_mixed`;
            const performance = t(perfKey);

            const insights = [];
            if (pattern === `proximity`) insights.push(window.mySimulation.t(`insight_proximity`));
            else if (pattern === `scale`) insights.push(window.mySimulation.t(`insight_scale`));
            else if (pattern === `digitized`) insights.push(window.mySimulation.t(`insight_digitized`));
            else if (pattern === `thin`) insights.push(window.mySimulation.t(`insight_thin`));
            else if (pattern === `unfinanced`) insights.push(window.mySimulation.t(`insight_unfinanced`));
            else insights.push(window.mySimulation.t(`insight_mixed`));

            if (!financed) insights.push(window.mySimulation.t(`insight_payback`));
            if (ds.csatCrash) insights.push(window.mySimulation.t(`insight_csatcrash`));
            if (csat < this.START_CSAT) insights.push(window.mySimulation.t(`insight_csat_low`));
            if (!fast) insights.push(window.mySimulation.t(`insight_ttd_high`));
            if (frontier && cheaper && delighted && financed) insights.push(window.mySimulation.t(`insight_frontier`));

            return {
                gradeKey: perfKey,
                score: composite,
                ttd: ttd,
                cost: cost,
                csat: csat,
                payback: payback,
                fast: fast,
                frontier: frontier,
                cheaper: cheaper,
                delighted: delighted,
                financed: financed,
                pattern: pattern,
                composite: composite,
                performance: performance,
                insights: insights
            };
        }

        getHint(state, results) {
            if (!results) return null;
            const ds = state.domainState;
            if (ds.builtFactoryThinking) return window.mySimulation.t(`hint_scale`);
            if (ds.overBudget) return window.mySimulation.t(`hint_overbudget`);
            if (ds.digitizedOnly) return window.mySimulation.t(`hint_digitized`);
            if (ds.spreadThin) return window.mySimulation.t(`hint_thin`);
            if (ds.csatCrash) return window.mySimulation.t(`hint_csatcrash`);
            if (state.currentPeriod >= 2 && ds.payback > this.PAYBACK_HURDLE) return window.mySimulation.t(`hint_payback`);
            if (ds.ttd <= 4 && ds.csat >= 84 && ds.payback > 0 && ds.payback <= this.PAYBACK_HURDLE) return window.mySimulation.t(`hint_strong`);
            if (ds.ttd >= 7) return window.mySimulation.t(`hint_ttd`);
            return null;
        }

        getHistoryTableConfig() {
            const self = this;
            return [
                { key: `period`, label: `Round`, i18nKey: `col_round` },
                { key: `results.summary`, label: `Move`, i18nKey: `col_move` },
                { key: `results.ttd`, label: `TTD`, i18nKey: `col_ttd`, formatter: (v) => self._ttdLabel(Number(v)) },
                { key: `results.cost`, label: `Unit cost`, i18nKey: `col_cost`, formatter: (v) => `฿${self._money(Math.round(Number(v)))}` },
                { key: `results.csat`, label: `CSAT`, i18nKey: `col_csat`, formatter: (v) => `${Math.round(Number(v))}` },
                { key: `results.payback`, label: `Payback`, i18nKey: `col_payback`, formatter: (v) => {
                    const n = Math.round(Number(v));
                    if (!n) return `—`;
                    if (n >= 999) return `∞`;
                    return `${n} ` + window.mySimulation.t(`unit_months`);
                } }
            ];
        }

        getPresets() { return null; }

        _updateBriefing(state) {
            const idx = Math.min((state.currentPeriod || 1) - 1, this.ROUNDS.length - 1);
            const round = this.ROUNDS[idx];
            const t = window.mySimulation ? window.mySimulation.t.bind(window.mySimulation) : (k) => k;

            const titleEl = document.getElementById(`briefingTitle`);
            if (titleEl) titleEl.textContent = t(round.titleKey);
            const textEl = document.getElementById(`briefingText`);
            if (textEl) textEl.innerHTML = t(round.textKey);
            const nameEl = document.getElementById(`roundNameDisplay`);
            if (nameEl) nameEl.textContent = t(round.nameKey);
            const clockEl = document.getElementById(`clockDisplay`);
            if (clockEl) clockEl.textContent = t(round.clockKey);

            for (let i = 0; i < this.ROUNDS.length; i++) {
                const panel = document.getElementById(this.ROUNDS[i].panelId);
                if (panel) panel.style.display = (i === idx) ? `block` : `none`;
            }
        }

